type Pack = {
  slug: string; title: string; description: string; ui: SolarBatteryAutonomyCalculatorUI;
  faq: { question: string; answer: string }[];
  howTo: { name: string; text: string }[];
  sections: [string, string, string, string, string, string, string, string];
  compare: [{ title: string; description: string; points: string[] }, { title: string; description: string; points: string[] }];
};

const iconA = 'mdi:clipboard-check-outline';
const iconB = 'mdi:alert-outline';

const makeContent = (pack: Pack, locale: string): ToolLocaleContent<SolarBatteryAutonomyCalculatorUI> => {
  const [title1, para1, title2, para2, title3, para3, title4, para4] = pack.sections;
  const faqSchema: WithContext<FAQPage> = { '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: pack.faq.map((item) => ({ '@type': 'Question', name: item.question, acceptedAnswer: { '@type': 'Answer', text: item.answer } })) };
  const howToSchema: WithContext<HowTo> = { '@context': 'https://schema.org', '@type': 'HowTo', name: pack.title, description: pack.description, step: pack.howTo.map((step) => ({ '@type': 'HowToStep', name: step.name, text: step.text })) };
  const appSchema: WithContext<SoftwareApplication> = { '@context': 'https://schema.org', '@type': 'SoftwareApplication', name: pack.title, description: pack.description, applicationCategory: 'UtilityApplication', operatingSystem: 'All', offers: { '@type': 'Offer', price: '0', priceCurrency: 'EUR' }, inLanguage: locale };
  return {
    slug: pack.slug, title: pack.title, description: pack.description, ui: pack.ui, faq: pack.faq, bibliography, howTo: pack.howTo, schemas: [faqSchema, howToSchema, appSchema],
    seo: [
      { type: 'title', text: title1, level: 2 },
      { type: 'paragraph', html: para1 },
      { type: 'stats', items: [{ value: 'W × h ÷ 1,000', label: pack.ui.loadWatts, icon: 'mdi:flash' }, { value: 'kWh × charge × efficiency', label: pack.ui.availableEnergy, icon: 'mdi:battery-check' }, { value: 'Available − planned', label: pack.ui.afterSchedule, icon: 'mdi:scale-balance' }], columns: 3 },
      { type: 'title', text: title2, level: 2 },
      { type: 'paragraph', html: para2 },
      { type: 'comparative', items: [{ ...pack.compare[0], icon: iconA }, { ...pack.compare[1], icon: iconB }], columns: 2 },
      { type: 'title', text: title3, level: 2 },
      { type: 'paragraph', html: para3 },
      { type: 'title', text: title4, level: 2 },
      { type: 'paragraph', html: para4 },
    ],
  };
};

