    ui: { setupEyebrow: 'IL TUO PIANO NOTTURNO', setupTitle: 'Crea una finestra realistica', capacityLabel: 'Capacità utile della batteria', chargeLabel: 'Carica iniziale', efficiencyLabel: 'Efficienza utile', loadsTitle: 'Carichi da mantenere attivi', loadName: 'Nome del carico', loadWatts: 'Potenza', loadHours: 'Ore', addLoad: 'Aggiungi carico', removeLoad: 'Rimuovi', resultEyebrow: 'IL RISULTATO', autonomyLabel: 'Autonomia stimata', availableEnergy: 'Disponibile ora', plannedDemand: 'Domanda prevista', afterSchedule: 'Dopo il programma', coverage: 'Copertura del programma', shortfall: 'Mancano', enoughEnergy: 'Questo piano rientra nell&apos;energia disponibile della batteria.', biggestLoad: 'Maggiore consumo energetico', shiftSuggestion: 'Sposta o spegni prima questo carico se ti serve più autonomia.', unitKwh: 'kWh', unitHours: 'h', unitWatts: 'W', unitPercent: '%', emptyLoads: 'Aggiungi almeno un carico per vedere la stima.' },
    faq: [{ question: 'Cosa significa autonomia della batteria?', answer: 'È il tempo stimato in cui la batteria può alimentare la potenza complessiva dei carichi inseriti. Il calcolo usa capacità utile, carica iniziale, efficienza e programma.' }, { question: 'Calcola anche la produzione solare diurna?', answer: 'No. È uno scenario notturno o di backup e non modella meteo, produzione solare, invecchiamento, limiti dell&apos;inverter o dimensionamento professionale.' }, { question: 'Perché includere l&apos;efficienza?', answer: 'Una parte dell&apos;energia si perde nell&apos;inverter e nei cavi. L&apos;efficienza rende la stima più prudente rispetto alla sola capacità nominale.' }, { question: 'Come posso aumentare l&apos;autonomia?', answer: 'Sposta lavatrice, acqua calda o ricarica dell&apos;auto fuori dalla finestra della batteria. Il risultato evidenzia il carico che consuma più energia.' }],
    howTo: [{ name: 'Inserisci la capacità utile', text: 'Usa il valore di energia utilizzabile indicato nella documentazione della batteria, in kilowattora.' }, { name: 'Imposta carica ed efficienza', text: 'Scegli la carica presente all&apos;inizio della notte e l&apos;efficienza utile stimata del sistema.' }, { name: 'Elenca i carichi', text: 'Aggiungi ogni apparecchio con potenza in watt e ore di funzionamento.' }, { name: 'Applica il risultato', text: 'Usa autonomia e carico principale per decidere cosa spostare o spegnere.' }],
    sections: ['Quanto dura la batteria solare durante la notte?', 'La domanda utile non è solo quanti kWh contiene la batteria, ma <strong>quante ore copre la tua notte reale</strong>. Frigorifero, router, luci e caricabatterie consumano a ritmi diversi. Inserisci i carichi che vuoi mantenere e ottieni una stima trasparente del backup.', 'Cosa mostra questo calcolatore di autonomia', 'Il risultato principale è l&apos;autonomia in ore, calcolata dalla potenza complessiva dei carichi. Mostra anche energia disponibile, domanda prevista, percentuale coperta ed eventuale deficit. Il maggior consumo suggerisce da dove iniziare.', 'Migliora il tuo piano di backup', 'Parti dai carichi importanti ma flessibili. Acqua calda, lavatrice, lavastoviglie e ricarica dell&apos;auto spesso possono essere spostati. Modifica un dato alla volta e confronta l&apos;energia residua.', 'Conosci i limiti della stima', 'È uno scenario di bilancio energetico, non un dimensionamento professionale. Meteo, produzione, degrado, picchi di potenza e limiti di sicurezza vanno verificati nella documentazione dell&apos;impianto.'],
    compare: [{ title: 'Rappresenta la tua notte', description: 'Confronta una routine completa con un piano per i soli carichi essenziali. Il calcolo resta nel browser e non accede al tuo impianto.', points: ['Usa la capacità utile', 'Indica le ore di ogni apparecchio', 'Confronta scenari rapidamente'] }, { title: 'Leggi i limiti', description: 'Il risultato è uno scenario trasparente, non una certificazione. Controlla sempre batteria e inverter secondo le istruzioni del produttore.', points: ['Nessuna previsione meteo', 'Nessun modello di degrado', 'Nessun consiglio di sicurezza'] }],
